const sourceCommit=execFileSync('git',['-C','../training-engine-baseline','rev-parse','HEAD'],{encoding:'utf8'}).trim();if(sourceCommit!=='0165768d37bcee81492c62f8b9ed0a573dd11521')throw Error('Expected the pinned pre-engine main checkout');
await mkdir(output,{recursive:true});const browser=await chromium.launch({headless:true}),page=await browser.newPage({viewport:{width:375,height:844}}),errors=[],blockedModels=[];
page.on('pageerror',error=>errors.push(error.message));await page.clock.setFixedTime(new Date('2026-10-15T03:00:00.000Z'));
await page.route('**/*',async route=>{const request=route.request(),url=new URL(request.url());if(url.origin!==base){await route.abort();return;}if(!url.pathname.startsWith('/api/')){await route.continue();return;}if(/assistant|coach|chat|completion/i.test(url.pathname))blockedModels.push(url.pathname);if(url.pathname.endsWith('/features'))return route.fulfill({json:{version:1,flags:{bodyProfile:true,themeDiscovery:true,planLifecycle:true,aiAssistantV2:false},expiresAt:Date.now()+3600000}});if(url.pathname.endsWith('/trial/access-status'))return route.fulfill({json:{qualification:'none',sessionValid:false,aiEnabled:false}});return route.fulfill({status:503,json:{error:'OFFLINE_FIXTURE_NO_MODEL'}});});
try{
 await page.goto(base);await page.getByLabel('你的回答').fill('保持健康，规律训练');await page.getByRole('button',{name:'继续',exact:true}).click();await page.getByLabel('说说你的身体情况').fill('男，34岁，170厘米，70公斤，腰围80厘米');await page.getByRole('button',{name:'继续',exact:true}).click();
 for(const text of ['每周2次，每次30分钟','在家，只有瑜伽垫']){await page.getByLabel('你的回答').fill(text);await page.getByRole('button',{name:'继续',exact:true}).click();}
 await page.getByRole('button',{name:'没有',exact:true}).click();await page.getByLabel('我已年满 18 岁').check();await page.getByRole('button',{name:'生成新计划',exact:true}).click();await expect(page.getByRole('heading',{name:'你的第一版计划',exact:true})).toBeVisible();await page.getByRole('button',{name:'就用这份计划',exact:true}).click();await page.getByRole('button',{name:'开始训练',exact:true}).first().click();await page.getByRole('button',{name:'完成这一组',exact:true}).click();await page.getByRole('button',{name:'暂停或结束',exact:true}).click();await page.getByRole('button',{name:'结束并记下',exact:true}).click();await page.getByRole('button',{name:'记下来',exact:true}).click();
 await page.goto(base+'/settings/body');await page.getByRole('button',{name:'体重（公斤） · 70 公斤',exact:true}).click();await page.getByRole('listbox').focus();await page.keyboard.press('ArrowDown');await page.getByRole('button',{name:'就用这个',exact:true}).click();await page.getByRole('button',{name:'保存身体资料',exact:true}).click();await expect(page.getByRole('status')).toHaveText('身体资料已保存');
 await page.goto(base+'/settings');await page.getByRole('button',{name:'备份恢复',exact:true}).click();const pending=page.waitForEvent('download');await page.getByRole('button',{name:'导出 JSON 备份',exact:true}).click();await(await pending).saveAs(destination);const bytes=await readFile(destination),backup=JSON.parse(bytes.toString());expect(backup.data.v8.workouts).toHaveLength(1);expect(backup.data.v8.workouts[0].sets).toHaveLength(1);expect(backup.data.bodyWeights.map(r=>r.weightGrams).sort()).toEqual([70000,71000]);expect(backup.data.v8.plans.length).toBeGreaterThan(0);expect(backup.data.profiles[0].bodyDetails.values.weightKg).toBe(71);expect(blockedModels).toEqual([]);expect(errors).toEqual([]);await page.screenshot({path:path.join(output,'baseline-export.png'),fullPage:true});
 const manifest={sourceCommit,browser:browser.version(),fixture:path.basename(destination),sha256:createHash('sha256').update(bytes).digest('hex'),bytes:bytes.length,synthetic:true,generator:'tests/fixtures/legacy-backups/generate-v8-main-pre-engine.mjs',inputMethod:'Actual baseline UI: body conversation, local plan adoption, one completed set, finish, appended weight, settings JSON download. No database writes or hand-authored fixture data.',network:'All API requests intercepted locally; external origins aborted; no model request attempted; cost 0',screen:'375x844 desktop Chromium proxy',recordedAt:new Date().toISOString()};await writeFile(destination.replace(/\.json$/,'.manifest.json'),JSON.stringify(manifest,null,2)+'\n');await writeFile(path.join(output,'result.json'),JSON.stringify({manifest,errors,blockedModels},null,2));console.log(JSON.stringify(manifest));
}finally{await browser.close();}
